query useTimelineItemsBackQuery(
  $id: ID!
  $count: Int!
  $cursor: String
) {
  node(id: $id) {
    __typename
    ... on Issue {
      backTimelineItems: timelineItems(last: $count, visibleEventsOnly: true, before: $cursor) {
        pageInfo {
          startCursor
        }
        totalCount
        edges {
          node {
            __typename
            ...IssueTimelineItem
            ... on Node {
              __isNode: __typename
              id
            }
          }
        }
      }
    }
    id
  }
}

