  author: search(type: ISSUE, first: $first, query: $author) {
    nodes {
      __typename
      ...PullRequestAndBranchPickerPullRequest
      ... on Node {
        __isNode: __typename
        id
      }
    }
  }
  open: search(type: ISSUE, first: $first, query: $open) {
    nodes {
